# PATCH-006-Final-Optimization-Polish.ps1
# CodeForge 2.0 - comprehensive plain-PHP optimization + polish pass
#
# This is an INCREMENTAL PATCH, not a project rebuild.
# It preserves config/.env and all existing database data (including PATCH-005 accounts).
#
# Run from:
#   D:\xampp\htdocs\codeforge
#
# Then:
#   powershell -ExecutionPolicy Bypass -File .\PATCH-006-Final-Optimization-Polish.ps1

$ErrorActionPreference = 'Stop'

function Write-Step([string]$Message) {
    Write-Host ''
    Write-Host "==> $Message" -ForegroundColor Cyan
}

function Write-Okay([string]$Message) {
    Write-Host "[OK]   $Message" -ForegroundColor Green
}

function Write-Warn([string]$Message) {
    Write-Host "[WARN] $Message" -ForegroundColor Yellow
}

$scriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path
$root = $scriptDir

if (-not (Test-Path (Join-Path $root 'core\bootstrap.php'))) {
    $root = (Get-Location).Path
}

if (-not (Test-Path (Join-Path $root 'core\bootstrap.php'))) {
    throw 'Could not find CodeForge project root. Put this patch inside D:\xampp\htdocs\codeforge and run it there.'
}

Set-Location $root

Write-Step 'Checking expected CodeForge state'

$indexPath = Join-Path $root 'index.php'
$dashboardPath = Join-Path $root 'dashboard.php'

if (-not (Test-Path $indexPath) -or -not (Test-Path $dashboardPath)) {
    throw 'index.php or dashboard.php is missing. PATCH-006 expects the dedicated landing-page build created by the earlier patches.'
}

$existingIndex = [System.IO.File]::ReadAllText($indexPath)
if ($existingIndex -notmatch 'forge-landing') {
    throw 'Current index.php is not the dedicated CodeForge landing page. Apply/fix the landing-page patches first, then run PATCH-006.'
}

Write-Okay 'Dedicated landing-page state detected'
Write-Okay 'dashboard.php exists separately'

$stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$backup = Join-Path $root "patch-backups\PATCH-006-$stamp"
New-Item -ItemType Directory -Force -Path $backup | Out-Null

