# Track which files existed before patching so rollback can remove newly added files.
$existedBefore = @{}

function Backup-AuditedFiles {
    Write-Step 'Backing up every file PATCH-006 will modify'

    foreach ($relative in $files.Keys) {
        $source = Join-Path $root $relative
        $exists = Test-Path $source
        $existedBefore[$relative] = $exists

        if ($exists) {
            $destination = Join-Path $backup $relative
            $parent = Split-Path -Parent $destination
            New-Item -ItemType Directory -Force -Path $parent | Out-Null
            Copy-Item $source $destination -Force
        }
    }

    Write-Okay "$($files.Count) audited file(s) prepared"
    Write-Host "Backup: $backup" -ForegroundColor DarkGray
}

function Restore-Backup {
    Write-Host ''
    Write-Host 'Rolling back PATCH-006 code changes...' -ForegroundColor Yellow

    foreach ($relative in $files.Keys) {
        $target = Join-Path $root $relative
        $backupFile = Join-Path $backup $relative

        if ($existedBefore[$relative]) {
            if (Test-Path $backupFile) {
                $parent = Split-Path -Parent $target
                New-Item -ItemType Directory -Force -Path $parent | Out-Null
                Copy-Item $backupFile $target -Force
            }
        } else {
            if (Test-Path $target) {
                Remove-Item $target -Force
            }
        }
    }

    Write-Warn 'Code files restored from the PATCH-006 backup.'
}

function Write-AuditedFiles {
    Write-Step 'Installing optimized audited files'

    $utf8NoBom = New-Object System.Text.UTF8Encoding($false)

    foreach ($relative in $files.Keys) {
        $encoded = ($files[$relative] -replace '\s', '')
        $bytes = [Convert]::FromBase64String($encoded)
        $content = [System.Text.Encoding]::UTF8.GetString($bytes)

        $target = Join-Path $root $relative
        $parent = Split-Path -Parent $target
        New-Item -ItemType Directory -Force -Path $parent | Out-Null

        [System.IO.File]::WriteAllText($target, $content, $utf8NoBom)
    }

    Write-Okay 'Optimized source/UI files installed without UTF-8 BOMs'
}

function Get-PHPExecutable {
    $xamppPhp = 'D:\xampp\php\php.exe'
    if (Test-Path $xamppPhp) {
        return $xamppPhp
    }

    $phpCommand = Get-Command php -ErrorAction SilentlyContinue
    if ($null -ne $phpCommand) {
        return $phpCommand.Source
    }

    throw 'PHP executable not found. Expected D:\xampp\php\php.exe.'
}

function Invoke-PHPLint([string]$phpExe) {
    Write-Step 'Linting the complete PHP project'

    $failed = @()
    $phpFiles = Get-ChildItem -Path $root -Recurse -File -Filter '*.php' | Where-Object {
        $_.FullName -notlike '*\patch-backups\*'
    }

    $savedPreference = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'

    foreach ($file in $phpFiles) {
        $output = & $phpExe -l $file.FullName 2>&1
        $exitCode = $LASTEXITCODE

        if ($exitCode -ne 0) {
            $failed += [PSCustomObject]@{
                File = $file.FullName
                Output = ($output -join [Environment]::NewLine)
            }
        }
    }

    $ErrorActionPreference = $savedPreference

    if ($failed.Count -gt 0) {
        foreach ($failure in $failed) {
            Write-Host "[FAIL] $($failure.File)" -ForegroundColor Red
            Write-Host $failure.Output
        }
        return $false
    }

    Write-Okay "$($phpFiles.Count) PHP file(s) passed syntax validation"
    return $true
}

function Invoke-AutomatedTests([string]$phpExe) {
    Write-Step 'Running CodeForge automated tests'

    $savedPreference = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    $output = & $phpExe (Join-Path $root 'tests\run.php') 2>&1
    $exitCode = $LASTEXITCODE
    $ErrorActionPreference = $savedPreference

    $output | ForEach-Object { Write-Host $_ }

    if ($exitCode -ne 0) {
        return $false
    }

    $joined = $output -join "`n"
    if ($joined -notmatch '27 passed, 0 failed') {
        Write-Warn 'Test command exited successfully, but the expected 27/0 summary was not found.'
        return $false
    }

    Write-Okay '27 automated tests passed'
    return $true
}

function Invoke-DatabaseOptimization([string]$phpExe) {
    Write-Step 'Optimizing the current MariaDB database'

    $optimizer = Join-Path $root 'database\optimize_cli.php'

    $savedPreference = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    $output = & $phpExe $optimizer 2>&1
    $exitCode = $LASTEXITCODE
    $ErrorActionPreference = $savedPreference

    $joined = $output -join "`n"

    if ($exitCode -eq 0 -and $joined -match 'Database optimization complete') {
        $output | ForEach-Object { Write-Host $_ }
        Write-Okay 'Database indexes/statistics optimized'
        return $true
    }

    Write-Warn 'Code optimization succeeded, but live DB index optimization could not be confirmed.'
    Write-Warn 'This normally means XAMPP MySQL is stopped or config/.env cannot currently connect.'
    Write-Host ''
    Write-Host 'When MySQL is running, execute:' -ForegroundColor Cyan
    Write-Host '  D:\xampp\php\php.exe database\optimize_cli.php' -ForegroundColor White

    if ($joined.Trim() -ne '') {
        Write-Host ''
        Write-Host 'Database optimizer output:' -ForegroundColor DarkGray
        $output | ForEach-Object { Write-Host $_ -ForegroundColor DarkGray }
    }

    return $false
}

Backup-AuditedFiles

try {
    Write-AuditedFiles

    $phpExe = Get-PHPExecutable

    if (-not (Invoke-PHPLint $phpExe)) {
        Restore-Backup
        throw 'PATCH-006 failed PHP syntax verification. Code changes were rolled back automatically.'
    }

    if (-not (Invoke-AutomatedTests $phpExe)) {
        Restore-Backup
        throw 'PATCH-006 failed the automated test suite. Code changes were rolled back automatically.'
    }

    Write-Step 'Verifying critical product behavior'

    $indexText = [System.IO.File]::ReadAllText((Join-Path $root 'index.php'))
    $dashboardText = [System.IO.File]::ReadAllText((Join-Path $root 'dashboard.php'))
    $headerText = [System.IO.File]::ReadAllText((Join-Path $root 'includes\header.php'))
    $polishText = [System.IO.File]::ReadAllText((Join-Path $root 'assets\css\polish.css'))
    $aggressiveText = [System.IO.File]::ReadAllText((Join-Path $root 'assets\css\aggressive.css'))

    if ($indexText -notmatch 'class="forge-landing"' -or $indexText -match 'require_login\s*\(') {
        Restore-Backup
        throw 'Landing-page verification failed. Code changes were rolled back.'
    }

    if ($dashboardText -notmatch 'require_login\s*\(') {
        Restore-Backup
        throw 'Dashboard authentication verification failed. Code changes were rolled back.'
    }

    if ($headerText -notmatch 'Space\+Grotesk' -or $polishText -notmatch 'Space Grotesk') {
        Restore-Backup
        throw 'Typography verification failed. Code changes were rolled back.'
    }

    if ($headerText -notmatch 'topbar-logout' -or $indexText -notmatch 'logout\.php') {
        Restore-Backup
        throw 'Logout-control verification failed. Code changes were rolled back.'
    }

    if ($aggressiveText -notmatch 'overscroll-behavior-y:\s*contain') {
        Restore-Backup
        throw 'Independent sidebar scrolling verification failed. Code changes were rolled back.'
    }

    Write-Okay 'index.php is still the public landing page'
    Write-Okay 'dashboard.php remains protected'
    Write-Okay 'Space Grotesk + JetBrains Mono font system active'
    Write-Okay 'Logout controls retained'
    Write-Okay 'Independent sidebar scrolling retained'

    # Database optimization is deliberately non-fatal because the user may run this
    # patch while MySQL is stopped. It does not rewrite/reset any data.
    $dbOptimized = Invoke-DatabaseOptimization $phpExe

    Write-Step 'PATCH-006 complete'

    Write-Host 'PATCH-006 APPLIED SUCCESSFULLY' -ForegroundColor Green
    Write-Host ''
    Write-Host 'What is now optimized:' -ForegroundColor Cyan
    Write-Host '  - Code DNA aggregation and memory usage'
    Write-Host '  - Ghost Race session isolation, selector load and concurrency guards'
    Write-Host '  - SQL Battle / SQL Lab read-only limits and sandbox protections'
    Write-Host '  - Profile, problem, university, contest and challenge aggregate queries'
    Write-Host '  - Query-specific MariaDB indexes'
    Write-Host '  - Session/API security and safer error exposure'
    Write-Host '  - Asset cache busting and browser rendering behavior'
    Write-Host '  - Landing animation performance and reduced-motion support'
    Write-Host '  - Responsive Code DNA chart and mobile navigation'
    Write-Host '  - Futuristic readable Space Grotesk + JetBrains Mono typography'
    Write-Host '  - Independent sidebar scrolling and visible logout controls'
    Write-Host ''
    Write-Host 'Landing:   http://localhost/codeforge/' -ForegroundColor White
    Write-Host 'Dashboard: http://localhost/codeforge/dashboard.php' -ForegroundColor White
    Write-Host ''
    Write-Host "Backup: $backup" -ForegroundColor DarkGray

    if ($dbOptimized) {
        Write-Host 'Database optimizer: COMPLETE' -ForegroundColor Green
    } else {
        Write-Host 'Database optimizer: DEFERRED (see warning above)' -ForegroundColor Yellow
    }

    Write-Host ''
    Write-Host 'Your existing config/.env and database records were NOT overwritten.' -ForegroundColor Yellow
    Write-Host 'PATCH-005 elite accounts remain in the live database.' -ForegroundColor Yellow
    Write-Host 'Asset versioning is automatic now; normal refresh should load changed CSS/JS.' -ForegroundColor Cyan

} catch {
    Write-Host ''
    Write-Host $_.Exception.Message -ForegroundColor Red
    Write-Host "Backup remains at: $backup" -ForegroundColor DarkGray
    exit 1
}
